#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');

// Only generated outputs; native projects are regenerated by Expo CNG.
for (const target of [
  'android',
  'ios',
  '.expo',
  '.kotlin',
  'dist',
  'coverage',
  'node_modules/.cache',
]) {
  fs.rmSync(path.join(root, target), { recursive: true, force: true });
}

function cleanPackage(packageDir) {
  for (const target of [
    'android/build',
    'android/.cxx',
    'android/.gradle',
    '.gradle',
    'android/expo-gradle-plugin/.gradle',
    'expo-dev-launcher-gradle-plugin/.gradle',
    'expo-module-gradle-plugin/.gradle',
    'apple/.DerivedData',
    'ios/.DerivedData',
  ]) {
    fs.rmSync(path.join(packageDir, target), { recursive: true, force: true });
  }

  cleanNodeModules(path.join(packageDir, 'node_modules'));
}

function cleanNodeModules(nodeModulesDir) {
  let entries;
  try {
    if (!fs.lstatSync(nodeModulesDir).isDirectory()) return;
    entries = fs.readdirSync(nodeModulesDir, { withFileTypes: true });
  } catch (error) {
    if (error.code === 'ENOENT') return;
    throw error;
  }

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const entryPath = path.join(nodeModulesDir, entry.name);
    if (entry.name.startsWith('@')) {
      for (const scopedPackage of fs.readdirSync(entryPath, { withFileTypes: true })) {
        if (scopedPackage.isDirectory()) cleanPackage(path.join(entryPath, scopedPackage.name));
      }
    } else {
      cleanPackage(entryPath);
    }
  }
}

cleanNodeModules(path.join(root, 'node_modules'));
